      "explain": "选C。舛互指对同一陈述对象既全部否定又部分肯定，或既全部肯定又部分否定。C\"全村人当时谁也不敢冒这个险，只有他背一身债承包了片荒山\"：前句\"全村人谁也不敢\"是全部否定（没有人冒险），后句\"只有他\"是部分肯定（仅他一人敢），先全否后部肯，正符合舛互\"既全部否定又部分肯定\"的特征，故属舛互。A\"除了下雨天，她几乎每天晚上都去父母家看看\"是对\"去父母家\"的整体肯定并附例外，不含\"全部肯定与部分否定\"的语义对立；B\"纯手工打造而成，连打磨也没有使用机械力\"是全部肯定（全程无机械），没有部分对立；D\"虽然听起来不可思议，但也不是一点道理都没有\"只是先贬后褒的转折让步，\"不可思议\"与\"有点道理\"并非对同一对象的全部肯定与部分否定（或反之）的对立关系，不符合舛互定义。故选C。",
