      "type": "define",
      "q": "决定性证据指的是依据法律不允许否认这种证据，或者是因为这种证据的强度和可信度足以压倒一切相反的证据并毫无疑问地证实主张。确证性证据亦称\"累积性证据\"\"追加性证据\"，指的是对以不同的方式支持同一事实或命题的证据具有强化或确证作用的证据。根据上述定义，关于以下事实哪项说法是正确的？在某案件中，被告甲坚称自己在案发当日并不在A市。调查中，乙证明自己当日未在A市遇到甲，丙证明在案发当日看见甲在无法到达现场的其他城市参加学术会议，随后，丁证明在该学术会议上，他看到甲、丙在进行学术讨论。",
