      "answer": 1,
      "explain": "定义要点：可分散风险是某些因素给个别证券带来损失的可能性；不可分散风险是某些因素给市场上所有证券均带来损失的可能性。逐项判断：A项，可分散风险的成因是某些因素，包括经营风险、财务风险、信用风险等，定义并未限定为个别企业经营不善，且“大多”缺乏依据，排除；B项，不可分散风险以同样方式影响市场上所有证券，投资者无论怎样分散持有证券组合都无法规避，符合定义，当选；C项，定义未对两类风险的损失大小作任何比较，无法推出，排除；D项，多个可分散风险叠加是否会演变为不可分散风险，定义未涉及，无依据，排除。故选 B。",
      "source": "超大杯刷题营·判断推理·第七组·2020事业单位"
