      "answer": 2,
      "explain": "有选择的专业化：选择多个细分市场（关联较小）。A产品专业化（同一类产品-冠心病药品推广到全国）；B市场专业化（针对少年儿童——一个顾客群，提供系列产品）；C瞄准\"职业男装\"和\"学龄儿童童鞋\"——两个不相关的细分市场（男装vs儿童鞋），有选择的专业化；D市场专业化（一个细分市场-边远农村家电）。",
